const items = $input.all();

const driveFiles = [];
const sheetRows = [];

// فصل الملفات عن الشيت
for (const item of items) {
  if (item.binary) {
    driveFiles.push(item);
  } else {
    sheetRows.push(item.json);
  }
}

// الملفات المعالجة مسبقًا
const processedNames = new Set(
  sheetRows
    .map(row => String(row.fileName || '').toLowerCase().trim())
    .filter(Boolean)
);

// منع التكرار داخل نفس التشغيل
const seenNames = new Set();

const newFiles = driveFiles.filter(item => {
  const fileName = item.binary?.data?.fileName?.toLowerCase().trim();

  if (!fileName) return false;

  if (processedNames.has(fileName)) return false;
  if (seenNames.has(fileName)) return false;

  seenNames.add(fileName);
  return true;
});

return newFiles.map(item => {
  const fileName = item.binary.data.fileName;

  return {
    json: {
      fileId: fileName, // نستخدم الاسم كـ ID
      fileName: fileName
    },
    binary: item.binary
  };
});

const file = $('Loop Over New CVs').first().json;
const extracted = $input.first().json;

const cleanText = (extracted.text || '')
  .replace(/\s+/g, ' ')
  .trim();

const analysisPrompt = `
Analyze this CV and extract structured recruitment information.

Return ONLY valid JSON.

CV CONTENT:
${cleanText}
`;

return [
  {
    json: {
      fileId: file.fileId || '',
      fileName: file.fileName || '',
      mimeType: file.mimeType || '',
      createdTime: file.createdTime || '',
      modifiedTime: file.modifiedTime || '',
      webViewLink: file.webViewLink || '',

      cvText: cleanText,

      analysisPrompt
    }
  }
];

