parameters.jsCode:
const data = $input.first().json;

const file = {
  fileId: data.fileId || '',
  fileName: data.fileName || '',
  webViewLink: data.webViewLink || ''
};

const safeArray = value => Array.isArray(value) ? value : [];

const primarySkills = safeArray(data.primary_skills);
const secondarySkills = safeArray(data.secondary_skills);
const technicalSkills = safeArray(data.technical_skills);
const roleKeywords = safeArray(data.role_keywords);
const industryKeywords = safeArray(data.industry_keywords);
const education = safeArray(data.education_json);
const certifications = safeArray(data.certifications_json);
const languages = safeArray(data.languages_json);

const positions = safeArray(data.experience_json?.positions);
const projects = safeArray(data.experience_json?.projects);

const searchText = [
  data.candidate_name,
  data.candidate_email,
  data.location,
  data.current_role,
  data.job_title,
  data.primary_role,
  data.role_category,
  data.seniority,
  ...primarySkills,
  ...secondarySkills,
  ...technicalSkills,
  ...roleKeywords,
  ...industryKeywords
].filter(Boolean).join(', ');

const pageContent = `
Candidate Name: ${data.candidate_name || 'Not specified'}

Current Role:
${data.current_role || data.job_title || 'Not specified'}

Primary Role:
${data.primary_role || 'Not specified'}

Role Category:
${data.role_category || 'Not specified'}

Seniority:
${data.seniority || 'Not specified'}

Years Experience:
${data.years_experience || 0}

Professional Summary:
${data.summary_text || 'Not specified'}

Primary Skills:
${primarySkills.join(', ') || 'Not specified'}

Secondary Skills:
${secondarySkills.join(', ') || 'Not specified'}

Technical Skills:
${technicalSkills.join(', ') || 'Not specified'}

Professional Experience:
${positions.map(p => `
${p.title || ''} at ${p.company || ''}
Duration: ${p.duration || ''}
${p.description || ''}
`).join('\n') || 'Not specified'}

Projects:
${projects.map(p => `
Project: ${p.name || ''}
Description: ${p.description || ''}
Technologies: ${safeArray(p.technologies).join(', ')}
Outcome: ${p.outcome || ''}
`).join('\n') || 'Not specified'}

Education:
${education.map(e => `
${e.degree || ''} - ${e.university || ''} (${e.year || ''})
`).join('\n') || 'Not specified'}

Certifications:
${certifications.map(c => `
${c.name || ''} - ${c.issuer || ''}
`).join('\n') || 'Not specified'}

Languages:
${languages.map(l => `
${l.language || ''} (${l.proficiency || ''})
`).join(', ') || 'Not specified'}

Role Keywords:
${roleKeywords.join(', ') || 'Not specified'}

Industry Keywords:
${industryKeywords.join(', ') || 'Not specified'}

ATS Score:
${data.ats_score || 0}

AI Relevance Score:
${data.ai_relevance_score || 0}

Data Relevance Score:
${data.data_relevance_score || 0}

Software Relevance Score:
${data.software_relevance_score || 0}
`.trim();

return [
  {
    json: {
      id:
        file.fileId ||
        data.fileId ||
        data.candidate_email ||
        `candidate_${Date.now()}`,

      pageContent,

      metadata: {
        candidate_name: data.candidate_name || '',
        candidate_email: data.candidate_email || '',
        phone: data.phone || '',
        location: data.location || '',
        linkedin: data.linkedin || '',

        current_role: data.current_role || data.job_title || '',
        primary_role: data.primary_role || '',
        role_category: data.role_category || '',
        seniority: data.seniority || '',
        years_experience: Number(data.years_experience || 0),

        ats_score: Number(data.ats_score || 0),
        ai_relevance_score: Number(data.ai_relevance_score || 0),
        data_relevance_score: Number(data.data_relevance_score || 0),
        software_relevance_score: Number(data.software_relevance_score || 0),

        primary_skills: primarySkills,
        secondary_skills: secondarySkills,
        technical_skills: technicalSkills,
        role_keywords: roleKeywords,
        industry_keywords: industryKeywords,

        search_text: searchText,

        fileId: file.fileId || data.fileId || '',
        fileName: file.fileName || data.fileName || '',
        webViewLink: file.webViewLink || data.webViewLink || '',

        source: 'cv_database'
      }
    }
  }
];

const input = $input.first().json;

let raw =
  input.output ||
  input.text ||
  input.response?.generations?.[0]?.[0]?.text ||
  input.choices?.[0]?.message?.content ||
  '';

if (!raw) {
  throw new Error('No AI output found');
}

if (typeof raw !== 'string') {
  raw = JSON.stringify(raw);
}

raw = raw
  .replace(/```json/g, '')
  .replace(/```/g, '')
  .trim();

const parsed = JSON.parse(raw);

return [
  {
    json: {
      ...parsed,

      fileId: input.fileId || '',
      fileName: input.fileName || '',
      webViewLink: input.webViewLink || '',
      createdTime: input.createdTime || '',
      modifiedTime: input.modifiedTime || ''
    }
  }
];

const raw = $input.first().json.output;

// ── 1. If plain text (Greeting / Identity response) ──────────────────────────
if (typeof raw === 'string') {
  const trimmed = raw.trim();
  const isJSON = trimmed.startsWith('{') || trimmed.startsWith('```');
  if (!isJSON) {
    return [{ json: { message: trimmed } }];
  }
}

// ── 2. Clean markdown fences if present ──────────────────────────────────────
let cleaned = typeof raw === 'string' ? raw : JSON.stringify(raw);
cleaned = cleaned
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/```$/i, '')
  .trim();

// ── 3. Parse JSON ─────────────────────────────────────────────────────────────
let data;
try {
  data = typeof cleaned === 'string' ? JSON.parse(cleaned) : cleaned;
} catch (e) {
  return [{ json: { message: raw } }];
}

// ── 4. Handle API error response ─────────────────────────────────────────────
if (data.success === false) {
  return [{
    json: {
      message: `⚠️ حدث خطأ أثناء البحث.\nيرجى المحاولة مرة أخرى لاحقاً.`
    }
  }];
}

// ── 5. Handle empty results ───────────────────────────────────────────────────
if (!data.candidates || data.candidates.length === 0) {
  return [{
    json: {
      message: `🔍 لا يوجد مرشحون مطابقون لهذه المعايير.\n\nجرّب تعديل الطلب أو استخدام كلمات مختلفة.`
    }
  }];
}

// ── 6. Helper: skip null/undefined/empty values ───────────────────────────────
const val = (v) => (v !== null && v !== undefined && v !== '' ? v : null);

// ── 7. Build message ──────────────────────────────────────────────────────────
let message = '';
message += `🔍 *نتائج البحث*\n`;
message += `━━━━━━━━━━━━━━\n`;
if (val(data.query))  message += `📌 الطلب: ${data.query}\n`;
if (val(data.count))  message += `👥 عدد النتائج: ${data.count}\n`;
message += `\n`;

for (const c of data.candidates) {
  message += `🏆 *#${c.rank}*\n`;

  if (val(c.candidate_name))         message += `👤 ${c.candidate_name}\n`;
  if (val(c.current_role))           message += `💼 ${c.current_role}\n`;
  if (val(c.role_category))          message += `🧩 ${c.role_category}\n`;
  if (val(c.location))               message += `📍 ${c.location}\n`;
  if (val(c.seniority))              message += `🎖 ${c.seniority}\n`;
  if (val(c.years_experience))       message += `📈 الخبرة: ${c.years_experience} سنة\n`;

  // Scores — only show if value exists
  const scores = [];
  if (val(c.ats_score))              scores.push(`ATS: ${c.ats_score}`);
  if (val(c.ai_relevance_score))     scores.push(`AI: ${c.ai_relevance_score}`);
  if (val(c.software_relevance_score)) scores.push(`SW: ${c.software_relevance_score}`);
  if (val(c.data_relevance_score))   scores.push(`Data: ${c.data_relevance_score}`);
  if (scores.length) message += `📊 ${scores.join(' | ')}\n`;

  // Skills
  if (c.primary_skills?.length) {
    message += `\n🛠 *المهارات:*\n`;
    message += c.primary_skills
      .slice(0, 8)
      .map(s => `• ${s}`)
      .join('\n');
    message += `\n`;
  }

  // Summary
  if (val(c.summary)) {
    const short = c.summary.length > 300
      ? c.summary.slice(0, 300) + '...'
      : c.summary;
    message += `\n📝 *الملخص:*\n${short}\n`;
  }

  // Reason
  if (val(c.reason)) {
    message += `\n📌 *سبب الاختيار:*\n${c.reason}\n`;
  }

  // Contact — always show section
  message += `\n📞 *التواصل:*\n`;
  message += val(c.candidate_email) ? `✉️ ${c.candidate_email}\n` : `✉️ غير متوفر\n`;
  message += val(c.phone)           ? `📱 ${c.phone}\n`           : `📱 غير متوفر\n`;

  message += `━━━━━━━━━━━━━━\n\n`;
}

return [{ json: { message: message.trim() } }];
